  const cap = capacity * per
  const states = new Map()
  return {
    type: 'bucket',
    advance(key, tick) {
      let state = states.get(key)
      if (!state) {
        state = { tokensNum: cap, lastTick: tick }
        states.set(key, state)
        return
      }
      const n = tick - state.lastTick
      if (n > 0n) {
        let next = state.tokensNum + refill * n
        if (next > cap) next = cap
        state.tokensNum = next
        state.lastTick = tick
      }
    },
    allows(key) {
      const state = states.get(key)
      return state.tokensNum >= per
    },
    record(key) {
      const state = states.get(key)
      state.tokensNum -= per
    },
  }
}

