import { createBucketPolicy, createWindowPolicy } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

function parseIntField(token, fieldName, min) {
  if (!INT_RE.test(token)) {
    throw new ParseError(`${fieldName} must be an integer of at least ${min}`)
  }
  const value = BigInt(token)
  if (value < BigInt(min)) {
    throw new ParseError(`${fieldName} must be an integer of at least ${min}`)
  }
  return value
}

function findRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix)) {
      if (best === null || route.prefix.length > best.prefix.length) {
        best = route
      }
    }
  }
  return best
}

/**
 * Parses and simulates the limiter file described by `input`, returning the
 * standard output text for the given mode. Throws a ParseError (with a
 * `line` number attached) on the first invalid line.
 */
export function processInput(input, mode) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const policies = new Map()
  const routes = []
  const routePrefixes = new Set()
  let hasEvents = false
  let lastTick = null

  const replayLines = []
  const perKeyStats = new Map()
  let totalAllowed = 0
  let totalDenied = 0

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    try {
      if (word === 'bucket' || word === 'window' || word === 'route') {
        if (hasEvents) {
          throw new ParseError('declarations must come before the first event')
        }
      }

      if (word === 'bucket') {
        if (tokens.length !== 5) {
          throw new ParseError('expected bucket <name> <capacity> <refill> <per>')
        }
        const [, name, capacityStr, refillStr, perStr] = tokens
        if (!NAME_RE.test(name)) throw new ParseError(`invalid policy name ${name}`)
        const capacity = parseIntField(capacityStr, 'capacity', 1)
        const refill = parseIntField(refillStr, 'refill', 0)
        const per = parseIntField(perStr, 'per', 1)
        if (policies.has(name)) throw new ParseError(`policy ${name} is declared twice`)
        policies.set(name, createBucketPolicy(capacity, refill, per))
      } else if (word === 'window') {
        if (tokens.length !== 4) {
          throw new ParseError('expected window <name> <limit> <span>')
        }
        const [, name, limitStr, spanStr] = tokens
        if (!NAME_RE.test(name)) throw new ParseError(`invalid policy name ${name}`)
        const limit = parseIntField(limitStr, 'limit', 0)
        const span = parseIntField(spanStr, 'span', 1)
        if (policies.has(name)) throw new ParseError(`policy ${name} is declared twice`)
        policies.set(name, createWindowPolicy(limit, span))
      } else if (word === 'route') {
        if (tokens.length < 3) {
          throw new ParseError('expected route <prefix> <policy>...')
        }
        const prefix = tokens[1]
        const policyNames = tokens.slice(2)
        if (!NAME_RE.test(prefix)) throw new ParseError(`invalid route prefix ${prefix}`)
        if (routePrefixes.has(prefix)) throw new ParseError(`prefix ${prefix} is routed twice`)
        for (const pn of policyNames) {
          if (!policies.has(pn)) throw new ParseError(`unknown policy ${pn}`)
        }
        routePrefixes.add(prefix)
        routes.push({ prefix, policyNames })
      } else if (word === 'event') {
        if (tokens.length !== 3) {
          throw new ParseError('expected event <tick> <key>')
        }
        const [, tickStr, key] = tokens
        const tick = parseIntField(tickStr, 'tick', 0)
        if (!NAME_RE.test(key)) throw new ParseError(`invalid key ${key}`)
        if (lastTick !== null && tick < lastTick) {
          throw new ParseError(`tick ${tick} is before tick ${lastTick}`)
        }
        hasEvents = true
        lastTick = tick

        const route = findRoute(routes, key)
        let allowed = true
        let denyPolicyName = null

        if (route) {
          for (const pn of route.policyNames) {
            policies.get(pn).advance(key, tick)
          }
          for (const pn of route.policyNames) {
            if (!policies.get(pn).allows(key)) {
              allowed = false
              denyPolicyName = pn
              break
            }
          }
          if (allowed) {
            for (const pn of route.policyNames) {
              policies.get(pn).record(key, tick)
            }
          }
        }

        if (!perKeyStats.has(key)) perKeyStats.set(key, { allowed: 0, denied: 0 })
        const stats = perKeyStats.get(key)
        if (allowed) {
          stats.allowed++
          totalAllowed++
          replayLines.push(`${tick} ${key} allow`)
        } else {
          stats.denied++
          totalDenied++
          replayLines.push(`${tick} ${key} deny ${denyPolicyName}`)
        }
      } else {
        throw new ParseError(`unknown directive ${word}`)
      }
    } catch (e) {
      if (e instanceof ParseError && e.line === undefined) {
        e.line = lineNo
      }
      throw e
    }
  }

  if (mode === 'replay') {
    return replayLines.map((l) => l + '\n').join('')
  }

  const keys = [...perKeyStats.keys()].sort()
  let out = ''
  for (const k of keys) {
    const s = perKeyStats.get(k)
    out += `${k} allowed=${s.allowed} denied=${s.denied}\n`
  }
  out += `total allowed=${totalAllowed} denied=${totalDenied}\n`
  return out
}
"}

