/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { processInput } from './engine.js'
import { ParseError } from './parse-error.js'

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

async function main() {
  const mode = process.argv[2]
  if (mode !== 'replay' && mode !== 'summary') {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
    return
  }

  const input = await readStdin()

  let output
  try {
    output = processInput(input, mode)
  } catch (e) {
    if (e instanceof ParseError) {
      process.stderr.write(`error: line ${e.line}: ${e.message}\n`)
      process.exit(2)
      return
    }
    throw e
  }

  process.stdout.write(output)
  process.exit(0)
}

main()
"}

